import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = re.compile(r'https?://[^\s\'"]+')
    urls = url_pattern.findall(myString if isinstance(myString, str) else "")
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        netloc = parsed.netloc
        if not netloc:
            continue
        domain = netloc.split("@")[-1].split(":")[0].strip()
        if domain:
            domains.add(domain)
    result = {}
    for domain in domains:
        try:
            resp = requests.get(f"http://ip-api.com/json/{domain}", params={"key": API_KEY}, timeout=10)
            if resp.status_code != 200:
                result[domain] = None
                continue
            try:
                data = resp.json()
            except ValueError:
                try:
                    data = json.loads(resp.text)
                except Exception:
                    data = None
            result[domain] = data
        except requests.RequestException:
            result[domain] = None
    return result
